CREATE TABLE IF NOT EXISTS economic_onboarding_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL, display_name text NOT NULL, business_type text NOT NULL, sector text NOT NULL, location text, description text, data_environment text NOT NULL DEFAULT 'production', onboarding_status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economic_identity_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL UNIQUE REFERENCES economic_onboarding_profiles(id) ON DELETE CASCADE, capture_score integer NOT NULL DEFAULT 0, evidence_score integer NOT NULL DEFAULT 0, verification_score integer NOT NULL DEFAULT 0, continuity_score integer NOT NULL DEFAULT 0, identity_stage text NOT NULL DEFAULT 'captured', readiness_score integer NOT NULL DEFAULT 0, gaps jsonb NOT NULL DEFAULT '[]'::jsonb, next_actions jsonb NOT NULL DEFAULT '[]'::jsonb, assessed_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());